import {esc,tr} from './views.mjs';

export const MENU_PHOTO_CHOICES=[
 ['basil-chicken','Basil chicken rice','ข้าวกะเพราไก่'],['chicken-rice','Chicken rice','ข้าวมันไก่'],
 ['fried-rice','Vegetable fried rice','ข้าวผัดผัก'],['tom-yum','Tom yum','ต้มยำ'],
 ['thai-tea','Thai iced tea','ชาไทยเย็น'],['lime-soda','Lime soda','มะนาวโซดา']
];
export function defaultMenuPhoto(item,demo=false){return item.photo===undefined&&demo&&MENU_PHOTO_CHOICES.some(([id])=>id===item.id)?{kind:'generated',key:item.id}:item.photo??null;}
export function photoChoiceFields(item,l,{demo=false,photoUrl=()=>'',hero=false}={}){
 const photo=defaultMenuPhoto(item,demo),choice=photo?.kind==='generated'?`generated:${photo.key}`:photo?.kind==='uploaded'?`uploaded:${photo.id}`:'none',url=photoUrl(photo);
 return `<div class="cp-menu-photo-editor"><div class="cp-menu-photo-preview"${hero?' data-dish-hero':''}><img data-photo-preview src="${esc(url||'')}" alt="" width="240" height="180" ${url?'':'hidden'}><span data-photo-empty ${url?'hidden':''}>${tr(l,'Your dish, in focus.','ให้ภาพอาหารเป็นจุดเด่น')}</span></div><div class="cp-menu-photo-controls"><label class="cp-field">${tr(l,'Menu image','ภาพเมนู')}<select name="photoChoice"><option value="none" ${choice==='none'?'selected':''}>${tr(l,'No photo','ไม่ใช้ภาพ')}</option><optgroup label="${tr(l,'AI image collection · illustrative','ชุดภาพ AI · ภาพประกอบ')}">${MENU_PHOTO_CHOICES.map(([key,en,th])=>`<option value="generated:${key}" ${choice===`generated:${key}`?'selected':''}>${tr(l,en,th)}</option>`).join('')}</optgroup>${photo?.kind==='uploaded'?`<option value="${esc(choice)}" selected>${tr(l,'My uploaded photo','ภาพที่ฉันอัปโหลด')}</option>`:''}</select></label><label class="cp-field">${tr(l,'Or use your real dish photo','หรือใช้ภาพอาหารจริงของคุณ')}<input type="file" data-dish-photo accept="image/jpeg,image/png,image/webp"><small>${tr(l,'JPEG, PNG or WebP · up to 8 MB','JPEG, PNG หรือ WebP · ไม่เกิน 8 MB')}</small></label><p class="cp-note" data-photo-status role="status">${tr(l,'AI images are illustrations. Your own photo shows your actual dish.','ภาพ AI เป็นภาพประกอบ ใช้ภาพของคุณเพื่อแสดงอาหารจริง')}</p></div></div>`;
}
export function menuImportView({language:l,demo,source='photo',preview=''}){
 return `<div class="cp-menu-import"><div class="cp-filters" role="group" aria-label="${tr(l,'Import method','วิธีนำเข้า')}"><button type="button" data-menu-source="photo" aria-pressed="${source==='photo'}">${tr(l,'Photo to menu','ภาพถ่ายเป็นเมนู')}</button><button type="button" data-menu-source="csv" aria-pressed="${source==='csv'}">${tr(l,'Import CSV','นำเข้า CSV')}</button></div>${source==='photo'?`
 <form id="cp-menu-photo-form" class="cp-form"><div class="cp-menu-import-preview">${preview?`<img src="${esc(preview)}" alt="${tr(l,'Your selected menu photo','ภาพเมนูที่คุณเลือก')}">`:`<div class="cp-menu-import-paper" aria-hidden="true"><small>SOI / MENU</small><span>01 &nbsp; กะเพราไก่</span><span>02 &nbsp; ข้าวมันไก่</span><span>03 &nbsp; ชาไทยเย็น</span></div>`}</div><label class="cp-field">${tr(l,'Take or choose a menu photo','ถ่ายหรือเลือกรูปเมนู')}<input id="cp-menu-source-photo" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"><small>${tr(l,'JPEG, PNG or WebP · up to 8 MB','JPEG, PNG หรือ WebP · ไม่เกิน 8 MB')}</small></label><label class="cp-field">${tr(l,'Dish imagery','ภาพอาหารในเมนู')}<select name="imageStyle"><option value="generated">${tr(l,'AI images · match the Soi theme','ภาพ AI · เข้ากับธีม Soi')}</option><option value="upload">${tr(l,'My real photos · add during review','ภาพจริงของฉัน · เพิ่มตอนตรวจสอบ')}</option></select></label><p class="cp-note">${demo?tr(l,'Simulated AI extraction: this walkthrough uses six sample dishes, not text from your photo. Edit every name and price before saving.','AI แยกข้อมูลจำลอง: ใช้หกเมนูตัวอย่าง ไม่ได้อ่านข้อความจากภาพของคุณ แก้ไขชื่อและราคาก่อนบันทึก'):tr(l,'Live photo recognition is not connected yet. Import a CSV or edit the menu directly.','ยังไม่เชื่อมการอ่านภาพด้วย AI จริง นำเข้า CSV หรือแก้ไขเมนูได้โดยตรง')}</p>${demo?`<button class="cp-button" type="submit">${tr(l,'Generate demo menu','สร้างเมนูเดโม')} →</button>`:`<a class="cp-button secondary" href="/copilot/demo#order">${tr(l,'Try photo import in the demo','ลองนำเข้าภาพในเดโม')} ↗</a>`}</form>`:`
 <form id="cp-menu-csv-form" class="cp-form"><p>${tr(l,'Bring your existing menu. Review names, prices and images before applying it. Matching SKU IDs update; other dishes stay. New dishes start paused until you enable them.','นำเมนูเดิมมาใช้ ตรวจชื่อ ราคา และภาพก่อนบันทึก SKU ที่ตรงกันจะอัปเดต เมนูอื่นยังคงอยู่ รายการใหม่จะพักไว้จนกว่าคุณจะเปิดขาย')}</p><label class="cp-field">${tr(l,'Menu CSV','ไฟล์ CSV เมนู')}<input name="csv" type="file" accept=".csv,text/csv" required></label><button class="cp-link" type="button" data-action="menu-csv-template">${tr(l,'Download menu template','ดาวน์โหลดตัวอย่างเมนู')} ↓</button><button class="cp-button" type="submit">${tr(l,'Review imported menu','ตรวจเมนูที่นำเข้า')} →</button></form>`}</div>`;
}
